function toast(msg){let t=$('.toast');if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.setAttribute('aria-live','polite');t.setAttribute('aria-atomic','true');document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');clearTimeout(t._x);t._x=setTimeout(()=>t.classList.remove('show'),2600)}
const PORTAL_PREFIX='FAP1',REPORT_PREFIX='FAR1';
function b64uBytes(bytes){let out='';const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);for(let i=0;i<a.length;i+=0x8000)out+=String.fromCharCode(...a.subarray(i,i+0x8000));return btoa(out).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function bytesB64u(text){let s=String(text||'').replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';const raw=atob(s),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a}
async function compressBytes(bytes){if(!('CompressionStream'in window))return{mode:'p',bytes};try{const stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));return{mode:'g',bytes:new Uint8Array(await new Response(stream).arrayBuffer())}}catch(_){return{mode:'p',bytes}}}
async function decompressBytes(bytes,mode){if(mode!=='g')return bytes;if(!('DecompressionStream'in window))throw Error('Ce navigateur ne peut pas ouvrir cet accès compressé.');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return new Uint8Array(await new Response(stream).arrayBuffer())}
async function createPortalToken(payload){const raw=new TextEncoder().encode(JSON.stringify(payload)),packed=await compressBytes(raw);if(!globalThis.crypto?.subtle)throw Error('La création d’un accès sécurisé nécessite HTTPS et Web Crypto. Utilise la version GitHub Pages.');const keyBytes=crypto.getRandomValues(new Uint8Array(32)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await crypto.subtle.importKey('raw',keyBytes,{name:'AES-GCM'},false,['encrypt']),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,packed.bytes);return`${PORTAL_PREFIX}.${packed.mode}.${b64uBytes(iv)}.${b64uBytes(keyBytes)}.${b64uBytes(cipher)}`}
async function decodePortalToken(token){token=String(token||'').trim();if(token.startsWith(PORTAL_PREFIX+'0.')){const [,mode,data]=token.split('.'),raw=await decompressBytes(bytesB64u(data),mode);return JSON.parse(new TextDecoder().decode(raw))}const parts=token.split('.');if(parts.length!==5||parts[0]!==PORTAL_PREFIX)throw Error('Code d’accès invalide.');if(!globalThis.crypto?.subtle)throw Error('Ce navigateur ne prend pas en charge le portail sécurisé.');const [,mode,ivTxt,keyTxt,cipherTxt]=parts,key=await crypto.subtle.importKey('raw',bytesB64u(keyTxt),{name:'AES-GCM'},false,['decrypt']),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytesB64u(ivTxt)},key,bytesB64u(cipherTxt)),raw=await decompressBytes(new Uint8Array(plain),mode);return JSON.parse(new TextDecoder().decode(raw))}
function portalTokenFromHash(){const h=location.hash.replace(/^#/,'');if(!h.startsWith('portal='))return'';try{return decodeURIComponent(h.slice(7))}catch(_){return h.slice(7)}}
