 if(intensity==='accessible'){const easier=pool.filter(x=>(+x.difficulty||3)<baseDiff);if(easier.length){pool=easier.sort((a,b)=>(+a.difficulty||3)-(+b.difficulty||3));directional=true}}
 else if(intensity==='intense'){const harder=pool.filter(x=>(+x.difficulty||3)>baseDiff);if(harder.length){pool=harder.sort((a,b)=>(+b.difficulty||3)-(+a.difficulty||3));directional=true}}
