 if(intensity==='accessible'){it.sets=adjustNumericSets(it.sets,-1);it.rest=adjustRest(it.rest,15);it.intensity='RPE 5–6 · garde 3–4 répétitions en réserve'}
 else if(intensity==='intense'){it.sets=adjustNumericSets(it.sets,1);it.rest=adjustRest(it.rest,-10);it.intensity='RPE 8–9 · arrête avant la perte de technique'}
 else if(it.type==='exercise'||it.id||it.variantExerciseId){it.intensity=it.intensity||'RPE 6–8 · garde 1–3 répétitions en réserve'}
