 if(load.summary)changes.unshift(load.summary);if(secondary)changes.unshift(`Objectif secondaire pris en compte : ${client.secondaryGoals}`);if(client?.quietMode==='Oui')changes.unshift('Mode discret : mouvements à fort impact évités');if(client?.limitedSpace==='Oui')changes.unshift('Espace réduit : déplacements longs évités');if(client?.allowRunning==='Non')changes.unshift('Course exclue selon la règle adhérent');if(client?.impactPreference==='Faible')changes.unshift('Impact faible : sauts et efforts très impactants évités');if(preferenceTerms(client?.likedExercises).length)changes.unshift('Préférences : mouvements appréciés conservés en priorité.');
