 if(tab==='demo')body=`${demoTriptych(e)}<div class="movement-levels">${movementAdaptationCard(e,'accessible','Plus facile','Moins de volume, plus de récupération')}${movementAdaptationCard(e,'standard','Normal','Version de référence')}${movementAdaptationCard(e,'intense','Plus intense','Plus exigeant, technique prioritaire')}</div>`;
