function render(){const r=routeName(),sameRoute=ui.route===r,winY=window.scrollY,modalY=$('.modal')?.scrollTop||0;ui.route=r;if(r==='portal-login'){renderPortalLogin();return}if(r==='portal'){renderPortal();return}let content='';if(r==='home')content=renderHome();else if(r==='clients')content=renderClients();else if(r==='client')content=renderClient(location.hash.split(':')[1]);else if(r==='create')content=renderCreate();else if(r==='programs')content=renderPrograms();else if(r==='movements')content=renderMovements();else content=renderNotFound('Page introuvable');$('#app').className='';$('#app').innerHTML=shell(content);if(sameRoute)requestAnimationFrame(()=>{const root=document.documentElement,oldScroll=root.style.scrollBehavior;root.style.scrollBehavior='auto';window.scrollTo(0,winY);const mc=$('.modal');if(mc)mc.scrollTop=modalY;requestAnimationFrame(()=>{root.style.scrollBehavior=oldScroll})})}
function choiceValues(name,root=document){return $$(`[data-choice="${name}"] button.on`,root).map(b=>b.dataset.value)}
function formObj(form){return Object.fromEntries(new FormData(form).entries())}
function makeItem(e){return {id:e.id,name:e.name,sets:'3',reps:e.mode==='duration'?'30 s':'10',rest:'60 s',tempo:'contrôlé',intensity:'RPE 6–8',cue:e.cues,fafaTip:e.fafaTip,variantExercise:e.name,variantExerciseId:e.id,type:'exercise',demoPattern:e.demoPattern}}
function syncEditorDraft(){const d=ui.editDraft;if(!d)return;const t=$('#edit-title'),o=$('#edit-objective'),du=$('#edit-duration'),fr=$('#edit-frequency');if(t)d.title=t.value;if(o)d.objective=o.value;if(du)d.duration=+du.value||45;if(fr)d.frequency=+fr.value||2;$$('.block-label').forEach(el=>{const bi=+el.dataset.bi;if(d.blocks[bi])d.blocks[bi].label=el.value});$$('.editor-row').forEach(row=>{const bi=+row.dataset.bi,ii=+row.dataset.ii,it=d.blocks?.[bi]?.items?.[ii];if(!it)return;$$('[data-field]',row).forEach(inp=>it[inp.dataset.field]=inp.value)})}
function selectClientModal(){return modal(`<span class="eyebrow">CRÉER POUR UN ADHÉRENT</span><h2>Pour qui programmes-tu ?</h2>${state.clients.length?`<div class="client-grid">${state.clients.map(c=>`<article class="client-card"><div class="client-avatar">${esc(clientInitials(c))}</div><div><h3>${esc(clientName(c))}</h3><p>${esc(c.goal||'Objectif')} · ${esc(c.sessionDuration||45)} min</p></div><div class="card-actions"><button class="btn primary small" data-action="choose-client-create" data-id="${c.id}">Choisir</button></div></article>`).join('')}</div>`:`<div class="empty"><strong>Aucun adhérent</strong><button class="btn primary" data-action="new-client">Créer une fiche</button></div>`}`,true)}
function setEditorModal(){ui.modal=editorModal(ui.editDraft);render()}
function restoreProgramModal(){if(ui.programGroup){ui.modal=renderProgramModal(ui.programGroup,ui.programBaseId,ui.intensity);render()}}
function restoreLive(){if(ui.live){ui.modal=liveModal();render()}}

