function finishLive(){const s=state.sessions.find(x=>x.id===ui.live.sessionId);if(!s)return;captureLiveInputs();const note=$('#live-note');if(note)ui.live.notes[ui.live.index]=note.value;s.status='completed';s.completedAt=new Date().toISOString();const items=flattenSession(s),performance=items.map((it,idx)=>({exerciseId:it.variantExerciseId||it.id||null,name:it.variantExercise||it.name,sets:ui.live.actual?.[idx]||[],rpe:ui.live.rpe?.[idx]??null,discomfort:ui.live.discomfort?.[idx]??0,pr:ui.live.prs?.includes(idx)||false,skipped:ui.live.skipped?.includes(idx)||false}));state.history.push({id:uid('history'),sessionId:s.id,clientId:s.clientId,programId:s.programId,title:s.title,completedAt:s.completedAt,rpe:ui.live.rpe,discomfort:ui.live.discomfort,notes:ui.live.notes,prs:ui.live.prs,skipped:ui.live.skipped,performance});save();ui.live=null;ui.modal=modal(`<div class="empty"><strong>Séance terminée</strong><span>Séries, répétitions/durée, charges, RIR, RPE, inconfort, notes et PR ont été enregistrés. La prochaine séance pourra s’appuyer sur ces données.</span><div class="actions" style="justify-content:center;margin-top:14px"><button class="btn primary" data-action="close-modal">Retour</button></div></div>`);render()}
async function handleRoute(){const r=routeName();if(r==='portal'){await activatePortalFromHash();return}render()}
function uniqueCatalog(items,labelKey){const seenId=new Set(),seenName=new Set(),out=[];for(const item of (items||[])){const id=String(item?.id||'').trim(),name=norm(item?.[labelKey]||item?.name||item?.title||'');if(!id||seenId.has(id)||!name||seenName.has(name))continue;seenId.add(id);seenName.add(name);out.push(item)}return out}
async function init(){try{const stored=window.FTStorage?await window.FTStorage.load():migrateState();state=normalizeState(stored);const cat=await window.FTCatalog.init();EX=uniqueCatalog(cat.exercises,'name');PROGRAMS=uniqueCatalog(cat.programs,'title');EX_BY_ID=new Map(EX.map(x=>[x.id,x]));PROGRAM_BY_ID=new Map(PROGRAMS.map(x=>[x.id,x]));if(!location.hash)history.replaceState(null,'','#home');await handleRoute()}catch(err){$('#app').className='boot';$('#app').innerHTML=`<div class="empty boot-error"><strong>FAFATRAINING n’a pas pu démarrer</strong><span>Le catalogue ou un fichier essentiel n’a pas été chargé. Aucun de tes adhérents n’est supprimé.</span><div class="actions" style="justify-content:center;margin-top:12px"><button class="btn secondary" onclick="location.reload()">Réessayer</button><a class="btn primary" href="./reset-cache.html">Actualiser les fichiers</a></div><details><summary>Diagnostic</summary><code>${esc(err?.message||String(err))}</code></details></div>`;console.error(err)}}

